      "path": "npm/bin/martty.js",
      "content": "#!/usr/bin/env node\n\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport { spawnSync } from 'node:child_process'\nimport { fileURLToPath } from 'node:url'\nimport { createInterface } from 'node:readline/promises'\nimport { resolveDependencyStack } from '../lib/agent.js'\nimport { bootClient, parseClientArgv, painterArgs, uiSettingsPath } from '../lib/boot.js'\nimport { runHarnessCommandAsync } from '../lib/harnesses.js'\nimport { nativeBinary } from '../lib/spawn-tui.js'\nimport { reportLaunchNotices, warnAboutLegacyPackage } from '../lib/install-migration.js'\nimport { planDshLaunch, runDshProfile, takeDshFlag } from '../lib/dsh-launch.js'\n\nconst __dirname = path.dirname(fileURLToPath(import.meta.url))\nconst configuredBin = process.env.MARTTY_BIN || process.env.DSH_TUI_BIN\n\nconst migrationNotices = []\nwarnAboutLegacyPackage({ argv1: process.argv[1], write: (line) => migrationNotices.push(line) })\nreportLaunchNotices(migrationNotices)\n\nconst argv = process.argv.slice(2)\nconst wantDemoSkin = argv.includes('--demo-skin')\nconst wantDemo = argv.includes('--demo')\nconst wantHelp = argv.includes('-h') || argv.includes('--help')\nconst wantVersion = argv.includes('-V') || argv.includes('--version')\n\nif (argv[0] === 'harness') {\n  const controller = new AbortController()\n  let interrupted = 0\n  const interrupt = (code) => {\n    interrupted = code\n    controller.abort(new Error('Harness operation cancelled'))\n  }\n  const onInterrupt = () => interrupt(130)\n  const onTerminate = () => interrupt(143)\n  process.on('SIGINT', onInterrupt)\n  process.on('SIGTERM', onTerminate)\n  let lastPhase, lastProgress = 0\n  let exitCode = 0\n  let defaults = []\n  try {\n    const agent = resolveDependencyStack()\n    defaults = [{\n      id: 'builtin-dsh',\n      label: 'Bundled DeepSeek Harness',\n      ...agent,\n      source: 'builtin',\n    }]\n  } catch {\n    // Source checkouts without installed dependencies still list PATH entries.\n  }\n  try {\n    const result = await runHarnessCommandAsync(argv.slice(1), {\n      settingsPath: uiSettingsPath(),\n      defaults,\n      columns: process.stdout.columns,\n      color: process.stdout.isTTY && process.env.NO_COLOR === undefined,\n      cwd: process.cwd(),\n      signal: controller.signal,\n      onProgress({ phase, receivedBytes }) {\n        const now = Date.now()\n        if (phase === lastPhase && now - lastProgress < 1000) return\n        lastPhase = phase; lastProgress = now\n        process.stderr.write(`Harness install: ${phase}${Number.isFinite(receivedBytes) ? ` · ${receivedBytes} bytes` : ''}\\n`)\n      },\n      ...(process.stdin.isTTY && process.stderr.isTTY ? { async confirmRemoval(preview) {\n        process.stderr.write(preview)\n        const prompt = createInterface({ input: process.stdin, output: process.stderr })\n        prompt.once('SIGINT', onInterrupt)\n        try {\n          const closed = new Promise(resolve => prompt.once('close', () => resolve('')))\n          const answer = await Promise.race([prompt.question('Remove this Harness? [y/N] ', { signal: controller.signal }), closed])\n          return /^y(es)?$/i.test(answer.trim())\n        } finally { prompt.close() }\n      } } : {}),\n    })\n    if (result.stdout) process.stdout.write(result.stdout)\n    if (result.stderr) process.stderr.write(result.stderr)\n    exitCode = interrupted || result.code\n  } catch (error) {\n    console.error(`martty harness: ${error instanceof Error ? error.message : String(error)}`)\n    exitCode = interrupted || (Number.isInteger(error?.exitCode) ? error.exitCode : 1)\n  } finally {\n    process.removeListener('SIGINT', onInterrupt)\n    process.removeListener('SIGTERM', onTerminate)\n  }\n  process.exit(exitCode)\n}\n\n// Validate startup arguments before resolving the native painter. A source\n// checkout must report the same usage errors as an installed package.\nlet parsed\nlet dshNotice\nif (!wantHelp && !wantVersion && !wantDemo && !wantDemoSkin) {\n  let dshPlan\n  try {\n    // `--dsh <profile>` attaches to the global dsh. Its version is checked\n    // before anything spawns: below a floor, Martty keeps its bundled\n    // harness and says why in the TUI; newer than tested only warns.\n    const { profile, rest } = takeDshFlag(argv)\n    if (profile !== null) dshPlan = planDshLaunch(profile, rest)\n    parsed = parseClientArgv(rest)\n    if (dshPlan?.mode === 'agent') parsed = { ...parsed, agent: dshPlan.agent }\n    if (dshPlan?.mode === 'bundled') console.error(`martty: ${dshPlan.notice.text}`)\n  } catch (error) {\n    const message = error instanceof Error ? error.message : String(error)\n    console.error(message.startsWith('martty:') ? message : `martty: ${message}`)\n    process.exit(Number.isInteger(error?.exitCode) ? error.exitCode : 1)\n  }\n  dshNotice = dshPlan?.notice\n  if (dshPlan?.mode === 'profile') {\n    // The profile carries Martty itself: dsh boots its Host tree and the\n    // profile's runner starts the TUI on this terminal.\n    process.exit(runDshProfile(dshPlan))\n  }\n}\n\nif (configuredBin && !fs.existsSync(configuredBin)) {\n  // Never silently fall back: the user believes they are running their\n  // own build (devlocalinstall.sh has caught this confusion before).\n  console.error(\n    `martty: ${configuredBin} (from ${process.env.MARTTY_BIN ? 'MARTTY_BIN' : 'DSH_TUI_BIN'})`\n      + ' does not exist — falling back to the installed native binary',\n  )\n}\nlet binaryPath\ntry {\n  binaryPath = nativeBinary({ envBin: configuredBin && fs.existsSync(configuredBin) ? configuredBin : null })\n} catch (error) {\n  console.error(`martty: ${error instanceof Error ? error.message : String(error)}`)\n  process.exit(1)\n}\n\nfunction exitFromSpawn(result) {\n  if (result.error) {\n    // A failed spawn (ENOENT, EACCES) sets status/signal to null; without\n    // a diagnostic the process would just exit 1 with no explanation.\n    console.error('martty: failed