      "path": "npm/lib/harness-registry.js",
      "content": "/** ACP Registry loading, normalization, and managed binary installation. */\n\nimport { createHash, randomUUID } from 'node:crypto'\nimport {\n  chmodSync,\n  createReadStream,\n  existsSync,\n  mkdirSync,\n  mkdtempSync,\n  renameSync,\n  rmSync,\n  statSync,\n  readFileSync,\n  writeFileSync,\n} from 'node:fs'\nimport path from 'node:path'\nimport { spawn } from 'node:child_process'\nimport { downloadFile } from './download.js'\n\nexport const ACP_REGISTRY_URL = 'https://cdn.agentclientprotocol.com/registry/v1/latest/registry.json'\n\nexport const OPENMA_PI_ACP = '@openma/pi-acp@latest'\nexport const OPENMA_PI_ACP_REPOSITORY = 'https://github.com/openma-ai/pi-acp'\n\nfunction preferMarttyPiAcp(records) {\n  return records.map((record) => record.id === 'pi-acp' ? {\n    ...record,\n    label: 'pi-acp',\n    version: 'latest',\n    // The official catalog also lists an unrelated unprefixed pi-acp package;\n    // Martty only ever launches @openma/pi-acp, and the repository URL is how\n    // users tell the two entries apart.\n    repository: OPENMA_PI_ACP_REPOSITORY,\n    distributions: [{\n      type: 'npx', command: 'npx', args: [OPENMA_PI_ACP], env: {},\n    }],\n  } : record)\n}\n\nfunction registryCachePath(options) {\n  return typeof options.settingsPath === 'string'\n    ? path.join(path.dirname(options.settingsPath), 'cache', 'acp-registry.json') : undefined\n}\n\n/** Last validated catalog, or the official bundled snapshot on first/offline launch. */\nexport function readAcpRegistrySnapshot(options = {}) {\n  const cachePath = registryCachePath(options)\n  if (cachePath !== undefined) {\n    try {\n      if (statSync(cachePath).size > 16 * 1024 * 1024) throw new Error('oversized cache')\n      const cached = JSON.parse(readFileSync(cachePath, 'utf8'))\n      if (cached.source === (options.registryUrl ?? ACP_REGISTRY_URL) && Array.isArray(cached.catalog?.agents)) {\n        return preferMarttyPiAcp(normalizeAcpRegistry(cached.catalog, opti